const phone = normalizarTelefonoArgentina(telefono);
// Antes no se mandaba el modelo y el cliente leía "tu nuevo Usser 0km".
const vehiculo = String(body.Modelo || '').trim() || String(body.Marca || '').trim() || 'vehículo';

return [{ json: {
  valido: Boolean(phone && nombre),
  campaign_id: 5975,
